pub fn find_max(a: &[i32]) -> usize {
    // Precondition: a is non-empty.
    let mut max_idx: usize = 0;

    for i in 1..a.len() {
        if a[i] > a[max_idx] {
            max_idx = i;
        }
    }

    max_idx
}

